import{_ as e,o as a,c as o,al as r}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"DroneCAN Lights","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/lights.md","filePath":"uk/dronecan/lights.md"}'),d={name:"uk/dronecan/lights.md"};function i(n,t,s,h,c,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="dronecan-lights" tabindex="-1">DroneCAN Lights <a class="header-anchor" href="#dronecan-lights" aria-label="Permalink to &quot;DroneCAN Lights&quot;">​</a></h1><p>PX4 can control external LEDs on a connected DroneCAN peripheral using the standard DroneCAN <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#lightscommand" target="_blank" rel="noreferrer">LightsCommand</a> message.</p><p>Up to 2 lights are supported. These can show <a href="./../getting_started/led_meanings#ui-led">system status colours</a>, a fixed colour (used for indicating aircraft orientation), or switch between both depending on arm state.</p><h2 id="пристроі-що-підтримуються" tabindex="-1">Пристрої, що підтримуються <a class="header-anchor" href="#пристроі-що-підтримуються" aria-label="Permalink to &quot;Пристрої, що підтримуються&quot;">​</a></h2><p>Any DroneCAN peripheral implementing the standard <code>LightsCommand</code> message type should work.</p><p>The following have been tested:</p><ul><li><strong>Vertiq ESC LED add-ons</strong>: Each ESC exposes two light IDs — one RGB (for status) and one white. The <code>light_id</code> for each is calculated as <code>esc_index × 3 + BASE_ID</code>, where <code>BASE_ID</code> is 1 for RGB and 2 for white. See <a href="./../peripherals/vertiq">Vertiq</a> for other ESC setup details.</li></ul><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><ol><li>Set up DroneCAN as described in <a href="./">DroneCAN</a> (<code>UAVCAN_ENABLE</code> ≥ 2).</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_LGT_NUM">UAVCAN_LGT_NUM</a> to the number of lights (1 or 2). Then reboot and reopen the ground station so that parameters for the new instances become visible.</li><li>Set the <code>light_id</code> and <a href="#light_functions">light functions</a> of each light: <ul><li><a href="./../advanced_config/parameter_reference#UAVCAN_LGT_ID0">UAVCAN_LGT_ID0</a> / <a href="./../advanced_config/parameter_reference#UAVCAN_LGT_ID1">UAVCAN_LGT_ID1</a>: Set to a <code>light_id</code> value (as defined by the specific product).</li><li><a href="./../advanced_config/parameter_reference#UAVCAN_LGT_FN0">UAVCAN_LGT_FN0</a> / <a href="./../advanced_config/parameter_reference#UAVCAN_LGT_FN1">UAVCAN_LGT_FN1</a>: Choose the desired <a href="#light_functions">light function</a>.</li></ul></li><li>Set <a href="#UAVCAN_LGT_MODE">UAVCAN_LGT_MODE</a> to control when fixed &quot;orientation&quot; colours activate.</li><li>Reboot for changes to take effect.</li></ol><h3 id="light_functions" tabindex="-1">Light Functions <a class="header-anchor" href="#light_functions" aria-label="Permalink to &quot;Light Functions {#light_functions}&quot;">​</a></h3><p>The functions of enabled lights are configured using <a href="./../advanced_config/parameter_reference#UAVCAN_LGT_FN0">UAVCAN_LGT_FN0</a> and <a href="./../advanced_config/parameter_reference#UAVCAN_LGT_FN1">UAVCAN_LGT_FN1</a>, respectively. Each function is represented by a value that defines two behaviours: one when the activation mode is <strong>inactive</strong> and one when it is <strong>active</strong>.</p><table tabindex="0"><thead><tr><th>Значення</th><th>Назва</th><th>When mode inactive</th><th>When mode active</th></tr></thead><tbody><tr><td>0</td><td>Status/Status</td><td>System status colour</td><td>System status colour</td></tr><tr><td>1</td><td>Off/White</td><td>Off</td><td>White</td></tr><tr><td>2</td><td>Off/Red</td><td>Off</td><td>Red</td></tr><tr><td>3</td><td>Off/Green</td><td>Off</td><td>Зелений</td></tr><tr><td>4</td><td>Status/White</td><td>System status colour</td><td>White</td></tr><tr><td>5</td><td>Status/Red</td><td>System status colour</td><td>Red</td></tr><tr><td>6</td><td>Status/Green</td><td>System status colour</td><td>Зелений</td></tr><tr><td>7</td><td>Status/Off</td><td>System status colour</td><td>Off</td></tr></tbody></table><p>Notes:</p><ul><li>The <a href="./../getting_started/led_meanings#ui-led">system status colours</a> is the same LED pattern used by the flight controller&#39;s onboard status LED (e.g. red when disarmed, green when armed and ready).</li><li>A fixed colour, commonly used to indicate aircraft orientation. For example it is a common convention to have a red light on the port side, green on starboard, or white to the rear. These colours do not change with flight controller state.</li><li>For <em>hybrid</em> functions, such as <code>Status/Red</code>, the light shows the Status colour while the activation mode is inactive, then switches to the &quot;fixed&quot; light colour once the mode becomes active.</li></ul><h3 id="UAVCAN_LGT_MODE" tabindex="-1">Activation Mode (<code>UAVCAN_LGT_MODE</code>) <a class="header-anchor" href="#UAVCAN_LGT_MODE" aria-label="Permalink to &quot;Activation Mode (`UAVCAN_LGT_MODE`) {#UAVCAN_LGT_MODE}&quot;">​</a></h3><p>The activation mode parameter (<a href="#UAVCAN_LGT_MODE">UAVCAN_LGT_MODE</a>) controls when each light switches from its <em>inactive</em> to its <em>active</em> behaviour (configured with the <a href="#light_functions">Light function</a>):</p><table tabindex="0"><thead><tr><th>Значення</th><th>Значення</th></tr></thead><tbody><tr><td>0</td><td>Always inactive (lights always show the inactive column)</td></tr><tr><td>1</td><td>Active when armed (default)</td></tr><tr><td>2</td><td>Active when prearmed or armed</td></tr><tr><td>3</td><td>Always active (lights always show the active column)</td></tr></tbody></table>',17)])])}const u=e(d,[["render",i]]);export{_ as __pageData,u as default};
